"""Human-readable HTML exported from persisted analyses, with no invented findings."""
from html import escape
import json
from evidence import public_https

def esc(value):return escape(str(value if value is not None else 'نامعلوم'),quote=True)
def num(value):return 'نامعلوم' if value is None else f'{value:,.0f}' if isinstance(value,(int,float)) else esc(value)
STATUS={'unknown':'نامعلوم','confirmed':'تأییدشده توسط کاربر','blocked':'مسدود','needs_review':'نیازمند بررسی','source_recorded':'منبع ثبت شده','signals_found':'نشانه یافت شد','source_observed':'منبع مشاهده‌شده','draft':'پیشنویس','open':'باز','calculated_scenario':'سناریوی ورودی کاربر','assessed_low_confidence':'ارزیابی با اطمینان پایین','low':'پایین','medium':'متوسط','insufficient':'ناکافی','completed':'اجرا شده','ready':'آماده','todo':'در صف','in_progress':'در حال انجام','done':'انجام شده'}
def label(value):return esc(STATUS.get(value,value))
CSS='''*{box-sizing:border-box}body{margin:0;background:#f2f5f9;color:#18334b;font:14px/1.9 Tahoma,Arial,sans-serif}main{max-width:1280px;margin:auto;padding:25px}header{padding:30px;background:#fff;border-bottom:1px solid #dce5ef}header h1{margin:0 0 8px;font-size:26px}h2{font-size:20px;margin:0 0 12px}h3{font-size:16px}p{margin:8px 0}.muted{color:#5b7184}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.two{display:grid;grid-template-columns:1.3fr 1fr;gap:16px}.card,section{background:#fff;border:1px solid #dce5ef;border-radius:14px;padding:20px;margin-bottom:16px}.metric{font-size:29px;font-weight:bold;color:#087a72}.tag{display:inline-block;background:#e2f4ef;color:#126258;padding:3px 10px;border-radius:20px}.warn{background:#fff5df;color:#76500c;border:1px solid #e8d4a9;padding:14px;border-radius:10px}.verdict{border-right:5px solid #087a72;padding:14px;background:#eaf7f3}.red{color:#a73032}button{border:1px solid #b8c9d6;border-radius:8px;background:#fff;color:#18334b;padding:9px 15px;margin:4px;cursor:pointer;font:inherit}button.active{background:#087a72;color:#fff;border-color:#087a72}a{color:#086c9b;overflow-wrap:anywhere}.tabs{position:sticky;top:0;background:#f2f5f9;padding:10px 0;z-index:2}.view[hidden],.case[hidden]{display:none}.scroll{overflow-x:auto}table{border-collapse:collapse;width:100%;min-width:650px}td,th{padding:12px;border-bottom:1px solid #e0e7ee;text-align:right;vertical-align:top}th{background:#f4f7fa;font-size:12px}details{border:1px solid #dce5ef;padding:12px;border-radius:9px;margin:9px 0}summary{cursor:pointer;font-weight:bold}.bar{height:9px;background:#e5edf3;border-radius:8px;overflow:hidden}.bar i{display:block;height:100%;background:#087a72}.source{border-right:3px solid #b8c9d6;padding-right:15px;overflow-wrap:anywhere}.count{font-size:20px;font-weight:bold}small{color:#5b7184}.step{padding:12px;border-right:3px solid #c6d9e5;margin:10px 0}@media(max-width:760px){main{padding:12px}.grid,.two{grid-template-columns:1fr}header{padding:20px}.tabs{position:static}header h1{font-size:21px}}@media print{button,.tabs{display:none}.view[hidden]{display:block}.case[hidden]{display:none}body{background:white}section,.card{break-inside:avoid}}'''
SCRIPT='''document.addEventListener('click',e=>{const c=e.target.closest('[data-case]');if(c){document.querySelectorAll('.case').forEach(x=>x.hidden=x.id!==c.dataset.case);document.querySelectorAll('[data-case]').forEach(x=>x.classList.toggle('active',x===c));return}const t=e.target.closest('[data-tab]');if(t){const root=t.closest('.case');root.querySelectorAll('.view').forEach(x=>x.hidden=x.dataset.view!==t.dataset.tab);root.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===t));}});'''

def body(analysis,title,sample=False,index=0):
 a=analysis;market=a['scores']['market_attractiveness'];fit=a['scores']['execution_feasibility'];econ=a['economics'];evidence=a['evidence'];gates=a['gates']
 unknown=[s['name'] for s in a['sections'] if s['status']=='unknown'];open_gates=[g for g in gates if g['status']!='confirmed'];context=a.get('opportunity_context',{})
 def metric(title,value,note):return f'<div class="card"><small>{esc(title)}</small><div class="metric">{num(value)}</div><p>{esc(note)}</p></div>'
 metrics=metric('اولویت پژوهش بازار / ۱۰۰',market['score'],'اطمینان '+STATUS.get(market['confidence'],market['confidence']))+metric('تناسب اولیه اجرا / ۱۰۰',fit['score'],'پوشش اطلاعات '+str(fit.get('coverage_percent',0))+'٪؛ اطمینان '+STATUS.get(fit['confidence'],fit['confidence']))+metric('شواهد منبع‌دار',len(evidence),'معامله تأییدشده: صفر؛ داده نمونه است' if sample else 'نشانه منبع، معامله تأییدشده نیست')
 tabs=''.join(f'<button data-tab="{key}" class="'+('active' if i==0 else '')+f'">{title}</button>' for i,(key,title) in enumerate([('summary','خلاصه تصمیم'),('proof','بازار و شواهد'),('economics','اقتصاد'),('execution','اجرای یک‌نفره و قیود'),('dossier','پرونده ۱۴‌بخشی')]))
 sources=''.join(f'<div class="source"><h3>{esc(e["title"])}</h3><p>{esc(e["excerpt"])}</p><small>مدرک: {esc(e["id"])} · {esc(e.get("published_at"))} · '+('داده ساختگی برای نمایش' if sample else label(e['evidence_status']))+'</small><p>'+ (f'<span>{esc(e["url"])}</span>' if sample or not public_https(e['url']) else f'<a href="{esc(e["url"])}" target="_blank" rel="noopener">بازکردن منبع اصلی</a>')+'</p></div>' for e in evidence) or '<p>شاهدی ثبت نشده است.</p>'
 factors=''.join(f'<li>{esc(x)}</li>' for x in market.get('factors',[]));fit_factors=''.join(f'<li>{esc(x)}</li>' for x in fit.get('factors',[]))
 gate_rows=''.join(f'<tr><td>{esc(g["title"])}</td><td>{label(g["status"])}</td><td>{esc(g["reason"])}</td></tr>' for g in gates)
 tasks=''.join(f'<div class="step"><b>{esc(t["order"])}. {esc(t["title"])}</b><p>{esc(t["action"])}</p><small>مسئول: {esc(t["owner"])} · وضعیت: {label(t["status"])}<br>شرط توقف: {esc(t["stop_condition"])}</small></div>' for t in a['validation_plan'])
 econ_rows=''.join(f'<tr><td>{name}</td><td>{num(None if key=='fixed_cost_period' and not econ.get('fixed_cost_known',False) else econ.get(key))}</td></tr>' for key,name in [('revenue_per_sale','درآمد هر فروش'),('variable_cost_per_sale','هزینه متغیر هر فروش'),('fixed_cost_period','هزینه ثابت دوره'),('contribution_per_sale','حاشیه مشارکت هر فروش'),('contribution_margin_percent','درصد حاشیه مشارکت'),('break_even_sales','تعداد فروش سربه‌سر')])
 sections=''.join(f'<details><summary>{esc(s["name"])} · {label(s["status"])}</summary><p>{esc(s["finding"])}</p><small>مدارک: {esc("، ".join(s.get("evidence_ids",[])) or "فاقد مدرک منبع‌دار")}</small></details>' for s in a['sections'])
 agent_rows=''.join(f'<tr><td>{esc(x["name"])}</td><td>{label(x["status"])}</td><td>{esc(x["purpose"])}</td></tr>' for x in a['agents'])
 counts={k:len(v) for k,v in a['evidence_categories'].items()}
 return f'''<article class="case" id="case-{index}" {'hidden' if index else ''}>
 <section><span class="tag">فرصت منتخب</span><h2>{esc(title)}</h2><p class="muted">مشتری: {esc(context.get('customer_segment'))} · حوزه: {esc(context.get('market_sector'))} · روش درآمد: {esc(context.get('business_model'))}</p></section>
 <div class="grid">{metrics}</div><nav class="tabs">{tabs}</nav>
 <div class="view" data-view="summary"><section><h2>آیا ارزش بررسی دارد؟</h2><div class="verdict"><b>{esc(a['decision']['label'])}</b><p>این پیشنهاد برای تصمیم درباره ادامهٔ بررسی است. تأیید نهایی تقاضا، سود و امکان اجرا هنوز به شواهد نیاز دارد.</p></div><div class="two"><div><h3>چرا این رتبه؟</h3><ul>{factors}</ul><p>{esc(market.get('reason'))}</p></div><div><h3>چه چیزی مانع اجراست؟</h3><p>{esc('، '.join(g['title'] for g in open_gates) or 'مانع ثبت‌شده‌ای وجود ندارد؛ تأیید انسانی همچنان لازم است')}</p><p>بخش‌های نامعلوم: {esc('، '.join(unknown) or 'به وضعیت بخش‌ها مراجعه کنید')}</p></div></div></section><section><h2>گام بعدی مشخص</h2>{tasks}</section></div>
 <div class="view" data-view="proof" hidden><section><h2>تقاضا، عرضه و شکاف</h2><div class="grid">{metric('نشانه نیاز/قصد خرید',counts.get('purchase_intent',0),'تعداد نشانه، تعداد خریدار مستقل نیست')}{metric('نشانه عرضه',counts.get('supply',0),'ظرفیت و کیفیت تأمین هنوز احراز نشده')}{metric('نشانه رقابت',counts.get('competition',0),'نبود نشانه به معنی نبود رقیب نیست')}</div><div class="warn">شکاف بازار اثبات نشده است. محل جست‌وجو، محل مشتری و محل تحویل یکسان فرض نمی‌شوند.</div></section><section><h2>پشت هر ادعا چه مدرکی هست؟</h2>{sources}</section></div>
 <div class="view" data-view="economics" hidden><section><h2>آیا پس از هزینه‌ها چیزی باقی می‌ماند؟</h2><p>{esc(econ['message'])}</p><p>واحد پول: {esc(econ.get('currency'))} · وضعیت: {label(econ['status'])}</p><div class="scroll"><table><thead><tr><th>قلم سناریو</th><th>مقدار</th></tr></thead><tbody>{econ_rows}</tbody></table></div><div class="warn">حاشیه مشارکت، سود خالص نیست. مالیات، کارمزد، هزینه ثابت و تحویل باید با اطلاعات واقعی کامل شوند. بدون ورودی معتبر، محاسبه‌ای ساخته نمی‌شود.</div></section></div>
 <div class="view" data-view="execution" hidden><section><h2>آیا برای توان شما مناسب است؟</h2><ul>{fit_factors}</ul><p>سهم زمانی کاربر، Agent و شریک اجرایی هنوز اندازه‌گیری نشده است.</p><div class="scroll"><table><thead><tr><th>شرط اجرا</th><th>وضعیت</th><th>اقدام لازم</th></tr></thead><tbody>{gate_rows}</tbody></table></div></section><section><h2>کدام دستیار چه کاری کرده است؟</h2><p>نقش‌های نرم‌افزاری قاعده‌محور؛ فعالیت عملیاتی زنده در داشبورد اصلی نمایش داده می‌شود.</p><div class="scroll"><table><thead><tr><th>نقش</th><th>وضعیت این تحلیل</th><th>وظیفه</th></tr></thead><tbody>{agent_rows}</tbody></table></div></section></div>
 <div class="view" data-view="dossier" hidden><section><h2>تمام بخش‌های پرونده</h2>{sections}</section></div></article>'''

def render_cases(cases,sample=False):
 sample=sample or any(a.get('sample_data',False) for a,title in cases)
 warning='<p class="warn"><b>نمایش با داده کاملاً فرضی</b> — این فایل خروجی واقعی موتور برنامه روی ورودی‌های نمونه است؛ هیچ فرصت، مشتری، قیمت یا منبع زنده‌ای را تأیید نمی‌کند.</p>' if sample else '<p class="muted">گزارش از تحلیل ذخیره‌شده ساخته شده است؛ محتوای منبع و ورودی کاربر مستقلاً تأیید نشده‌اند.</p>'
 choose=''.join(f'<button data-case="case-{i}" class="'+('active' if i==0 else '')+f'">{esc(title)}</button>' for i,(a,title) in enumerate(cases))
 comparison='<div class="scroll"><table><thead><tr><th>فرصت</th><th>اولویت بازار</th><th>تناسب اجرا</th><th>حاشیه هر فروش</th><th>تصمیم فعلی</th></tr></thead><tbody>'+''.join(f'<tr><td><button data-case="case-{i}">{esc(title)}</button></td><td>{num(a["scores"]["market_attractiveness"]["score"])}</td><td>{num(a["scores"]["execution_feasibility"]["score"])}</td><td>{num(a["economics"].get("contribution_per_sale"))}</td><td>{esc(a["decision"]["label"])}</td></tr>' for i,(a,title) in enumerate(cases))+'</tbody></table></div>'
 return '<!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>خروجی تصمیم‌یار فرصت درآمدی</title><style>'+CSS+'</style><header><h1>از فرصت تا تصمیم قابل بررسی</h1><p>کجا نیاز دیده شده؟ چرا ارزش بررسی دارد؟ قدم بعدی چیست؟</p>'+warning+'</header><main>'+('<section><h2>انتخاب فرصت برای مشاهدهٔ خروجی</h2>'+comparison+'</section>' if len(cases)>1 else '')+''.join(body(a,title,sample,i) for i,(a,title) in enumerate(cases))+'</main><script>'+SCRIPT+'</script></html>'

def render_report(analysis,title):return render_cases([(analysis,title)])
